/**
 * Mount the panel's JSON routes.
 *
 * @param ctx - the host plugin context.
 * @param config - plugin configuration; every key is an override of a default.
 */
export function apply(ctx, config = {}) {
  const store = createConfigStore(config)
  const options = { ctx, store }
  ctx.effect(() => ctx.webServer.register({
    kind: 'prefix',
    path: PANEL_ROUTE,
    handler: (req, res) => {
      void handlePanel(req, res, options)
    },
  }), 'dsh-image-studio: panel routes')
  void registerTool(ctx, options)
}

/**
 * Offer the ComfyUI run as a conversational tool.
 *
 * The tool runtime is optional: some profiles carry no `tools` service, some
 * have no attachment store to hand images back through. Neither shortage may
 * take the panel down, so registration is best-effort and every failure stays
 * silent — the workbench keeps its own ComfyUI mode either way.
 */
async function registerTool(ctx, options) {
  try {
    const defineTool = await resolveDefineTool()
    await ctx.inject(['tools'], async (toolCtx) => {
      if (typeof toolCtx.tools?.register !== 'function') return
      await toolCtx.inject(['attachments'], (attachCtx) => {
        const input = {
          run: (body) => comfyRun(options, body),
          admit: (file) => attachCtx.attachments.saveImage({
            data: file.data,
            mediaType: file.mediaType,
            ...(typeof file.name === 'string' && file.name !== '' ? { name: file.name } : {}),
          }),
        }
        // A Host that hands out `defineTool` gets the shorthand; every other Host
        // takes the raw definition, which needs no factory and no import.
        toolCtx.tools.register(typeof defineTool === 'function' ? defineTool(makeComfyToolSpec(input)) : makeComfyTool(input))
        attachCtx.effect(() => () => {}, 'dsh-image-studio: ' + TOOL_NAME + ' with attachments')
      })
    })
  } catch {
    // No tool runtime reachable here; the panel itself does not depend on one.
  }
}

/**
 * Dispatch one panel request.
 *
 * @param req - the incoming HTTP request.
 * @param res - the response to write.
 */
async function handlePanel(req, res, options) {
  const path = new URL(String(req.url ?? '/'), 'http://localhost').pathname
  const routes = {
    '/config': ['GET', null, 0],
    '/config/save': ['POST', null, 0],
    '/status': ['GET', null, 0],
    '/models': ['GET', null, 0],
    '/gallery': ['GET', null, 0],
    '/image': ['GET', null, 0],
    '/delete': ['POST', null, 0],
    '/generate': ['POST', null, DEFAULT_GENERATE_TIMEOUT_MS],
    '/comfy/generate': ['POST', null, DEFAULT_GENERATE_TIMEOUT_MS],
    '/comfy/workflows': ['GET', null, 20000],
    '/llm/config': ['GET', '/v1/llm/config', 10000],
    '/llm/save': ['POST', '/v1/llm/config', 10000],
    '/llm/test': ['POST', '/v1/llm/test', 45000],
    '/assistant': ['POST', '/v1/studio/assistant', DEFAULT_GENERATE_TIMEOUT_MS],
  }
  const route = routes[path.slice(PANEL_ROUTE.length)]
  if (!path.startsWith(PANEL_ROUTE + '/') || !route) {
    sendJson(res, 404, { error: 'unknown panel route' })
    return
  }
  if (req.method !== route[0]) {
    res.setHeader('Allow', route[0])
    sendJson(res, 405, { error: 'method not allowed' })
    return
  }
  if (req.method === 'POST') {
    const origin = req.headers.origin
    let sameOrigin = true
    try { if (origin) sameOrigin = new URL(origin).host === req.headers.host } catch { sameOrigin = false }
    if (!sameOrigin || req.headers['sec-fetch-site'] === 'cross-site') {
      sendJson(res, 403, { error: 'cross-origin mutation rejected' })
      return
    }
  }
  try {
    if (path === PANEL_ROUTE + '/image') {
      await sendGalleryImage(req, res)
      return
    }
    const body = req.method === 'POST'
      ? await readBody(req, isLargeBodyPath(path) ? MAX_BODY_BYTES : JSON_BODY_BYTES)
      : undefined
    if (route[1] !== null) {
      await proxyJson(res, route[1], body, route[2], options)
      return
    }
    switch (path.slice(PANEL_ROUTE.length)) {
      case '/config':
        await handleConfig(res, options)
        return
      case '/config/save':
        await handleConfigSave(res, options, parseBody(body))
        return
      case '/status':
        await handleStatus(res, options)
        return
      case '/models':
        await handleModels(req, res, options)
        return
      case '/gallery':
        await handleGallery(res)
        return
      case '/delete':
        await handleDelete(res, parseBody(body))
        return
      case '/generate':
        await handleGenerate(res, options, parseBody(body))
        return
      case '/comfy/generate':
        await handleComfyGenerate(res, options, parseBody(body))
        return
      case '/comfy/workflows':
        await handleComfyWorkflows(req, res, options)
        return
      default:
        sendJson(res, 404, { error: 'unknown panel route' })
    }
  } catch (error) {
    sendJson(res, error.status ?? 400, { error: error.message ?? 'invalid request' })
  }
}

/** Bodies that may carry base64 image data, so they get the larger read budget. */
function isLargeBodyPath(path) {
  return path === PANEL_ROUTE + '/generate' || path === PANEL_ROUTE + '/comfy/generate'
}

/** Parse an already-read JSON body, tolerating an absent one. */
function parseBody(body) {
  return body === undefined ? {} : JSON.parse(body)
}

/**
 * Report the provider catalog and the current configuration.
 *
 * The API key never crosses this route: only its reference name, and whether
 * that reference currently resolves, are described.
 */
async function handleConfig(res, options) {
  const config = await options.store.load()
  const key = await describeKey(options, config.keyRef)
  const agent = agentTarget(config)
  sendJson(res, 200, {
    providers: PROVIDERS.map((provider) => ({
      id: provider.id,
      label: provider.label,
      family: provider.family,
      baseURL: provider.baseURL,
      apiKeyRef: provider.apiKeyRef,
      supportsSize: provider.supportsSize,
      supportsQuality: provider.supportsQuality,
      editFormats: provider.editFormats,
    })),
    editFormats: EDIT_FORMATS,
    maxReferenceBytes: MAX_IMAGE_BYTES,
    config: publicConfig(config),
    key,
    agent: { baseUrl: agent.baseUrl, apiKey: agent.apiKey !== '' },
    comfy: { baseUrl: comfyTarget(config) },
  })
}

/**
 * Persist a configuration change.
 *
 * A non-empty `apiKey` is a *new secret*: it is written through the credential
 * service so it lands in the provider-managed store rather than in cleartext
 * beside the panel's own settings.
 */
async function handleConfigSave(res, options, body) {
  const patch = {}
  const textKeys = ['provider', 'baseURL', 'model', 'keyRef', 'editFormat', 'size', 'quality', 'aspectRatio', 'imageSize', 'workflow', 'comfyBaseUrl', 'agentBaseUrl']
  for (const key of textKeys) {
    if (typeof body[key] !== 'string') continue
    patch[key] = body[key].trim()
  }
  if (patch.provider !== undefined && !providerById(patch.provider)) {
    sendJson(res, 400, { error: '未知的图像服务：' + patch.provider })
    return
  }
  if (patch.keyRef !== undefined && patch.keyRef !== '' && !isCredentialRefName(patch.keyRef)) {
    sendJson(res, 400, { error: '密钥引用名只能由字母、数字和下划线组成，且不能以数字开头' })
    return
  }
  if (patch.comfyBaseUrl !== undefined) {
    try {
      comfyBaseUrl(patch.comfyBaseUrl)
    } catch (error) {
      sendJson(res, 400, { error: error.message ?? 'ComfyUI 地址无效' })
      return
    }
  }
  if (patch.agentBaseUrl !== undefined && patch.agentBaseUrl !== '') {
    try {
      agentBaseUrl(patch.agentBaseUrl)
    } catch (error) {
      sendJson(res, 400, { error: error.message ?? 'Agent 地址无效' })
      return
    }
  }
  if (patch.editFormat !== undefined && patch.editFormat !== '' && !EDIT_FORMATS.includes(patch.editFormat)) {
    sendJson(res, 400, { error: '未知的编辑格式：' + patch.editFormat })
    return
  }
  const apiKey = typeof body.apiKey === 'string' ? body.apiKey.trim() : ''
  const config = await options.store.save(patch)
  if (apiKey !== '') {
    const ref = patch.keyRef || config.keyRef
    if (!isCredentialRefName(ref)) {
      sendJson(res, 400, { error: '密钥引用名无效，无法写入密钥' })
      return
    }
    try {
      await options.ctx.credentials.set(ref, apiKey)
    } catch (error) {
      sendJson(res, 400, { error: '写入密钥失败：' + (error?.message ?? String(error)) })
      return
    }
  }
  sendJson(res, 200, { ok: true, config: publicConfig(await options.store.load()), key: await describeKey(options, (await options.store.load()).keyRef) })
}

/** Report whether the configured credential currently resolves, without its value. */
async function describeKey(options, ref) {
  if (!isCredentialRefName(ref)) return { ref, configured: false, source: null, writable: false }
  try {
    const info = await options.ctx.credentials.describe(ref)
    return { ref, configured: Boolean(info?.configured), source: info?.source ?? null, writable: Boolean(info?.writable) }
  } catch {
    return { ref, configured: false, source: null, writable: false }
  }
}

/** A minimal readiness probe for the panel header. */
async function handleStatus(res, options) {
  const config = await options.store.load()
  const key = await describeKey(options, config.keyRef)
  sendJson(res, 200, {
    ready: key.configured && config.model !== '',
    provider: config.provider,
    model: config.model,
    keyConfigured: key.configured,
    count: MAX_GENERATE_COUNT,
    timeoutMs: Number(config.generateTimeoutMs) > 0 ? Number(config.generateTimeoutMs) : DEFAULT_GENERATE_TIMEOUT_MS,
  })
}

/**
 * Read the model catalog of the configured or requested provider.
 *
 * The dropdown is populated from here rather than from a hardcoded list, so a
 * relay's own model ids appear without a panel release. The API key stays on
 * this side: it is resolved here and only the resulting ids cross to the browser.
 */
async function handleModels(req, res, options) {
  const config = await options.store.load()
  const query = new URL(String(req.url ?? '/'), 'http://localhost').searchParams
  const requested = query.get('provider') ?? ''
  const providerId = requested !== '' ? requested : config.provider
  const provider = providerById(providerId)
  if (!provider) {
    sendJson(res, 400, { error: '未知的图像服务：' + String(providerId) })
    return
  }
  const baseURL = query.get('baseURL') || config.baseURL || provider.baseURL
  const keyRef = config.keyRef || provider.apiKeyRef
  if (!isCredentialRefName(keyRef)) {
    sendJson(res, 400, { error: '密钥引用名无效，请先在「模型配置」中修正' })
    return
  }
  let apiKey = ''
  try {
    apiKey = (await options.ctx.credentials.resolve(keyRef))?.value.trim() ?? ''
  } catch (error) {
    sendJson(res, 500, { error: '读取密钥失败：' + (error?.message ?? String(error)) })
    return
  }
  if (apiKey === '') {
    sendJson(res, 400, { error: provider.label + ' 尚未配置 API Key：请在「模型配置」中填写并保存密钥（引用名 ' + keyRef + '）' })
    return
  }
  try {
    const models = await listModels({ provider: provider.id, baseURL, apiKey })
    sendJson(res, 200, { ok: true, provider: provider.id, models })
  } catch (error) {
    // A model catalog is a convenience, never a hard dependency: surface the
    // reason but let the user keep typing a model id by hand.
    sendJson(res, 502, { error: error?.message ?? String(error) })
  }
}

/** List the images this panel has generated, newest first. */
async function handleGallery(res) {
  const images = await listGallery()
  sendJson(res, 200, { images })
}

/** Stream one generated image back to the browser. */
async function sendGalleryImage(req, res) {
  const query = new URL(String(req.url ?? '/'), 'http://localhost').searchParams
  const name = query.get('name') ?? ''
  if (!safeGalleryName(name)) {
    res.writeHead(400, { 'Content-Type': 'text/plain; charset=utf-8' })
    res.end('invalid image name')
    return
  }
  try {
    const bytes = await readFile(join(GALLERY_DIR, name))
    const mediaType = imageMediaType(mediaTypeForName(name)) ?? 'application/octet-stream'
    res.writeHead(200, {
      'Content-Type': mediaType,
      'Content-Length': String(bytes.length),
      'Cache-Control': 'no-cache',
    })
    res.end(bytes)
  } catch {
    res.writeHead(404, { 'Content-Type': 'text/plain; charset=utf-8' })
    res.end('not found')
  }
}

/** Remove one generated image. */
async function handleDelete(res, body) {
  const name = typeof body.name === 'string' ? body.name : ''
  if (!safeGalleryName(name)) {
    sendJson(res, 400, { error: 'invalid image name' })
    return
  }
  try {
    await unlink(join(GALLERY_DIR, name))
    sendJson(res, 200, { ok: true })
  } catch {
    sendJson(res, 404, { error: 'not found' })
  }
}

/**
 * Generate or edit one image and store the result.
 *
 * The request carries the prompt and, for an edit, base64 reference images. No
 * binary upload route is needed: the reference bytes are already in the body the
 * browser sent, and the panel's own credential is the only secret involved.
 */
async function handleGenerate(res, options, body) {
  const config = await options.store.load()
  const providerId = typeof body.provider === 'string' && body.provider !== '' ? body.provider : config.provider
  const provider = providerById(providerId)
  if (!provider) {
    sendJson(res, 400, { error: '未知的图像服务：' + String(providerId) })
    return
  }
  const model = stringOr(body.model, config.model)
  if (model === '') {
    sendJson(res, 400, { error: '请先在「模型配置」中填写模型名称' })
    return
  }
  const prompt = typeof body.prompt === 'string' ? body.prompt.trim() : ''
  if (prompt === '') {
    sendJson(res, 400, { error: '请输入提示词' })
    return
  }
  const negative = typeof body.negative === 'string' ? body.negative.trim() : ''
  const finalPrompt = negative === '' ? prompt : prompt + '\n\n不要出现：' + negative
  const keyRef = config.keyRef || provider.apiKeyRef
  if (!isCredentialRefName(keyRef)) {
    sendJson(res, 400, { error: '密钥引用名无效，请先在「模型配置」中修正' })
    return
  }
  let apiKey = ''
  try {
    apiKey = (await options.ctx.credentials.resolve(keyRef))?.value.trim() ?? ''
  } catch (error) {
    sendJson(res, 500, { error: '读取密钥失败：' + (error?.message ?? String(error)) })
    return
  }
  if (apiKey === '') {
    sendJson(res, 400, { error: provider.label + ' 尚未配置 API Key：请在「模型配置」中填写并保存密钥（引用名 ' + keyRef + '）' })
    return
  }
  const referenceImages = readReferenceImages(body.referenceImages)
  if (referenceImages.error) {
    sendJson(res, 400, { error: referenceImages.error })
    return
  }
  // An explicit mode wins. Without one, keep the old heuristic: a caller that
  // attached references meant image-to-image.
  const mode = STUDIO_MODES.includes(body.mode)
    ? body.mode
    : (referenceImages.list.length > 0 ? 'edit' : 'generate')
  if (mode === 'edit' && referenceImages.list.length === 0) {
    sendJson(res, 400, { error: '图生图至少需要一张参考图' })
    return
  }
  const count = normalizeCount(body.count)
  const timeoutMs = Number(config.generateTimeoutMs) > 0 ? Number(config.generateTimeoutMs) : DEFAULT_GENERATE_TIMEOUT_MS
  const startedAt = Date.now()
  const images = []
  const failures = []
  for (let index = 0; index < count; index += 1) {
    const controller = new AbortController()
    const timer = setTimeout(() => controller.abort(), timeoutMs)
    try {
      const request = {
        provider: provider.id,
        apiKey,
        baseURL: config.baseURL || provider.baseURL,
        model,
        prompt: finalPrompt,
        size: stringOr(body.size, config.size),
        quality: stringOr(body.quality, config.quality),
        aspectRatio: stringOr(body.aspectRatio, config.aspectRatio),
        imageSize: stringOr(body.imageSize, config.imageSize),
        maxBytes: MAX_IMAGE_BYTES,
        signal: controller.signal,
      }
      const result = mode === 'edit'
        ? await editImage({ ...request, referenceImages: referenceImages.list, editFormat: config.editFormat || provider.editFormats[0] || 'multipart' })
        : await generateImage(request)
      const name = await saveGalleryImage(result.data, result.mediaType)
      images.push({
        name,
        mediaType: result.mediaType,
        bytes: result.data.length,
        url: PANEL_ROUTE + '/image?name=' + encodeURIComponent(name),
      })
    } catch (error) {
      failures.push(describeFailure(error, timeoutMs))
    } finally {
      clearTimeout(timer)
    }
  }
  if (images.length === 0) {
    const first = failures[0]
    sendJson(res, first?.timeout === true ? 504 : 502, { error: first?.message ?? '生成失败' })
    return
  }
  sendJson(res, 200, {
    ok: true,
    provider: provider.id,
    model,
    mode,
    count: images.length,
    requested: count,
    elapsedMs: Date.now() - startedAt,
    image: images[0],
    images,
    ...(failures.length > 0 ? { partialError: failures.map((entry) => entry.message).join('\n') } : {}),
  })
}

/**
 * List the workflows a local ComfyUI server has saved.
 *
 * ComfyUI keeps saved workflows in its own user-data tree and exposes no
 * `/workflows` route, so the listing comes from its user-data endpoint. The
 * panel only ever reads here; nothing is written back.
 *
 * `baseUrl` in the query is the address currently typed in the form, so a
 * machine can be listed before its address is saved. An address that cannot be
 * used is a 400 (the user can fix the box); an unreachable server is a 502.
 */
async function handleComfyWorkflows(req, res, options) {
  const config = await options.store.load()
  const query = new URL(String(req.url ?? '/'), 'http://localhost').searchParams
  const requested = (query.get('baseUrl') ?? '').trim()
  let baseUrl
  try {
    baseUrl = requested === '' ? comfyTarget(config) : comfyBaseUrl(requested)
  } catch (error) {
    sendJson(res, 400, { error: error?.message ?? 'ComfyUI 地址不合法' })
    return
  }
  try {
    const { workflows } = await listWorkflows(baseUrl)
    sendJson(res, 200, { ok: true, baseUrl, workflows })
  } catch (error) {
    sendJson(res, 502, { error: error?.message ?? '读取 ComfyUI 工作流失败' })
  }
}

/**
 * Run one ComfyUI workflow and copy its output into the panel gallery.
 *
 * The reference image, if any, is uploaded into ComfyUI's input directory
 * first, because that is what its `LoadImage` node reads; the resulting file
 * name is what the panel writes into the graph. Everything after that happens
 * on the ComfyUI server: the prompt is queued, polled to completion, and the
 * produced images are downloaded through `/view` and stored in the gallery so
 * the result behaves exactly like an image-service result.
 *
 * Both callers want verbatim agent text, so failures carry a `status` that the
 * HTTP handler can turn into an HTTP reply.
 */
async function comfyRun(options, body) {
  const config = await options.store.load()
  const prompt = typeof body.prompt === 'string' ? body.prompt.trim() : ''
  if (prompt === '') throw badRequest('请输入提示词')
  const workflow = stringOr(body.workflow, config.workflow)
  if (workflow === '') throw badRequest('请先在「生成方式」中选择一个 ComfyUI 工作流')
  const reference = readComfyReference(body.reference)
  if (reference.error) throw badRequest(reference.error)
  const baseUrl = typeof body.baseUrl === 'string' && body.baseUrl.trim() !== ''
    ? comfyBaseUrl(body.baseUrl)
    : comfyTarget(config)
  const timeoutMs = Number(config.generateTimeoutMs) > 0 ? Number(config.generateTimeoutMs) : DEFAULT_GENERATE_TIMEOUT_MS
  const startedAt = Date.now()
  try {
    const { graph, converted } = await readWorkflow(baseUrl, workflow, timeoutMs)
    const placement = applyPrompt(graph, prompt, typeof body.negative === 'string' ? body.negative.trim() : '')
    let initImage = null
    if (reference.image) {
      const uploaded = await uploadImage({
        baseUrl,
        data: reference.image.data,
        mediaType: reference.image.mediaType,
        name: uploadName(reference.name, reference.image.mediaType),
      })
      if (!applyInitImage(graph, uploaded.name)) {
        throw new Error('这个工作流里没有 LoadImage 节点，无法使用参考图；请改用「文生图」或换一个支持图生图的工作流。')
      }
      initImage = uploaded.name
    }
    const run = await runWorkflow({ baseUrl, graph, timeoutMs })
    const images = []
    const files = []
    for (const image of run.images) {
      if (image.data.length === 0 || image.data.length > MAX_IMAGE_BYTES) continue
      const name = await saveGalleryImage(image.data, image.mediaType)
      images.push({
        name,
        mediaType: image.mediaType,
        bytes: image.data.length,
        url: PANEL_ROUTE + '/image?name=' + encodeURIComponent(name),
      })
      files.push({ data: image.data, mediaType: image.mediaType, name })
    }
    return {
      ok: true,
      workflow,
      mode: 'comfy',
      baseUrl,
      count: images.length,
      elapsedMs: Date.now() - startedAt,
      image: images[0] ?? null,
      images,
      files,
      ...(converted ? { note: '这个工作流是 UI 格式，面板已自动转换成 API 格式后提交。' } : {}),
      ...(initImage !== null ? { initImage } : {}),
      ...(placement.strategy === 'fallback'
        ? { note: '工作流里没有找到 KSampler 的提示词连线，已按节点顺序写入第一个和第二个文本编码节点；请确认生成结果符合预期。' }
        : {}),
      promptId: run.promptId,
    }
  } catch (error) {
    if (error?.status === undefined) error.status = 502
    throw error
  }
}

/** Serve one ComfyUI run over HTTP, using the pipeline the tool also uses. */
async function handleComfyGenerate(res, options, body) {
  try {
    const result = await comfyRun(options, body)
    // `files` carries image bytes for the conversational tool; the browser gets
    // the gallery URLs instead.
    const { files, ...answer } = result
    void files
    sendJson(res, 200, answer)
  } catch (error) {
    sendJson(res, error?.status ?? 502, { error: error?.message ?? 'ComfyUI 生成失败' })
  }
}

/** A caller-side mistake, reported to the browser as a 400. */
function badRequest(message) {
  const error = new Error(message)
  error.status = 400
  return error
}

/** Where the panel's ComfyUI routes point. */
function comfyTarget(config) {
  const raw = String(config.comfyBaseUrl || process.env.DSH_IMAGE_STUDIO_COMFY_URL || DEFAULT_COMFY_BASE_URL)
  return raw.replace(/\/+$/, '')
}

/** Call one Agent route and hand back both the parsed body and the raw text. */
async function callAgent(agent, agentPath, body, timeoutMs) {
  const controller = new AbortController()
  const timer = setTimeout(() => controller.abort(), timeoutMs)
  try {
    const upstream = await fetch(agent.baseUrl + agentPath, {
      method: 'POST',
      headers: requestHeaders(agent.apiKey, true),
      body: JSON.stringify(body),
      signal: controller.signal,
    })
    const text = await upstream.text()
    let parsed
    try { parsed = JSON.parse(text) } catch { parsed = undefined }
    return { status: upstream.status, data: parsed, text }
  } catch (error) {
    const aborted = error instanceof Error && error.name === 'AbortError'
    const failure = new Error(aborted
      ? '请求超时（' + String(Math.round(timeoutMs / 1000)) + ' 秒）'
      : '无法连接或读取 Agent：请检查 Agent 是否已启动。')
    failure.status = aborted ? 504 : 502
    throw failure
  } finally {
    clearTimeout(timer)
  }
}

/** The Agent's own error text when it answered with one, else a short dump. */
function describeAgentFailure(answer) {
  const error = answer?.data?.error
  if (typeof error === 'string' && error !== '') return error
  return String(answer?.text ?? '').trim().slice(0, 500) || 'Agent 没有返回结果'
}

/** One request's failure, in the shape every caller already understands. */
function describeFailure(error, timeoutMs) {
  const aborted = error instanceof Error && error.name === 'AbortError'
  return {
    timeout: aborted,
    message: aborted
      ? '生成请求超时（' + String(Math.round(timeoutMs / 1000)) + ' 秒）'
      : '生成失败：' + (error?.message ?? String(error)),
  }
}

/** Clamp a requested batch size to the range the panel offers. */
function normalizeCount(value) {
  const number = Math.trunc(Number(value))
  if (!Number.isFinite(number) || number < 1) return 1
  return number > MAX_GENERATE_COUNT ? MAX_GENERATE_COUNT : number
}

/** Validate and decode the base64 reference images in one request body. */
function readReferenceImages(value) {
  if (value === undefined || value === null) return { list: [] }
  if (!Array.isArray(value)) return { error: '参考图必须是数组', list: [] }
  if (value.length > 4) return { error: '参考图最多 4 张', list: [] }
  const list = []
  for (const entry of value) {
    if (typeof entry !== 'object' || entry === null) return { error: '参考图格式无效', list: [] }
    const encoded = typeof entry.data === 'string' ? entry.data : ''
    const declared = String(entry.mediaType ?? '')
    if (encoded === '') return { error: '参考图缺少数据', list: [] }
    let bytes
    try {
      bytes = Buffer.from(encoded, 'base64')
    } catch {
      return { error: '参考图数据不是有效的 base64', list: [] }
    }
    if (bytes.length === 0) return { error: '参考图数据为空', list: [] }
    if (bytes.length > MAX_IMAGE_BYTES) {
      return { error: '单张参考图超过 ' + String(Math.round(MAX_IMAGE_BYTES / 1024 / 1024)) + ' MB 上限', list: [] }
    }
    const data = new Uint8Array(bytes)
    const mediaType = imageMediaType(declared)
    if (!mediaType) return { error: '参考图必须是 PNG、JPEG、WebP 或 GIF', list: [] }
    list.push({ data, mediaType })
  }
  return { list }
}

/** Write one generated image into the gallery directory under a fresh name. */
async function saveGalleryImage(data, mediaType) {
  await mkdir(GALLERY_DIR, { recursive: true })
  const name = 'img-' + timestamp(new Date()) + '-' + randomBytes(3).toString('hex') + '.' + extensionFor(mediaType)
  await writeFile(join(GALLERY_DIR, name), data)
  return name
}

/** Enumerate the gallery directory, newest first. */
async function listGallery() {
  let names
  try {
    names = await readdir(GALLERY_DIR)
  } catch {
    return []
  }
  const entries = []
  for (const name of names) {
    if (!safeGalleryName(name)) continue
    const mediaType = imageMediaType(mediaTypeForName(name))
    if (!mediaType) continue
    try {
      const info = await stat(join(GALLERY_DIR, name))
      if (!info.isFile()) continue
      entries.push({ name, mediaType, bytes: info.size, createdAt: info.mtimeMs, url: PANEL_ROUTE + '/image?name=' + encodeURIComponent(name) })
    } catch {
      continue
    }
  }
  entries.sort((left, right) => right.createdAt - left.createdAt)
  return entries
}

/** Accept only a bare file name that resolves inside the gallery directory. */
function safeGalleryName(name) {
  return typeof name === 'string' && name.length > 0 && !/[\\/:\x00]/.test(name) && !name.includes('..')
}

/** The media type implied by a gallery file name's extension. */
function mediaTypeForName(name) {
  const lowered = name.toLowerCase()
  if (lowered.endsWith('.png')) return 'image/png'
  if (lowered.endsWith('.jpg') || lowered.endsWith('.jpeg')) return 'image/jpeg'
  if (lowered.endsWith('.webp')) return 'image/webp'
  if (lowered.endsWith('.gif')) return 'image/gif'
  return ''
}

/** `YYYYMMDD-HHMMSS` in local time, for sortable file names. */
function timestamp(date) {
  const pad = (value) => String(value).padStart(2, '0')
  return String(date.getFullYear())
    + pad(date.getMonth() + 1)
    + pad(date.getDate())
    + '-'
    + pad(date.getHours())
    + pad(date.getMinutes())
    + pad(date.getSeconds())
}

/**
 * Validate a user-entered Agent base URL.
 *
 * Same rule as the ComfyUI address: http(s) only, no credentials in the URL.
 * An empty value is accepted and means "use the built-in default".
 */
function agentBaseUrl(value) {
  const raw = String(value ?? '').trim().replace(/\/+$/, '')
  if (raw === '') return raw
  let parsed
  try {
    parsed = new URL(raw)
  } catch {
    throw new Error('Agent 地址不是有效的 URL：' + raw)
  }
  if (parsed.protocol !== 'http:' && parsed.protocol !== 'https:') {
    throw new Error('Agent 地址必须是 http(s) URL：' + raw)
  }
  if (parsed.username !== '' || parsed.password !== '') {
    throw new Error('Agent 地址不能带用户名和密码：' + raw)
  }
  return raw
}

/**
 * Where the panel's Agent routes point, and the key they authenticate with.
 *
 * The Agent is an external service the user runs, so its address comes from
 * this panel's settings or from `DSH_IMAGE_STUDIO_AGENT_URL`. The key is read
 * *only* from `DSH_IMAGE_STUDIO_AGENT_API_KEY`: it has no credential reference
 * and must never be written into this panel's own settings file.
 */
function agentTarget(config) {
  return {
    baseUrl: String(config.agentBaseUrl || process.env.DSH_IMAGE_STUDIO_AGENT_URL || DEFAULT_AGENT_BASE_URL).replace(/\/+$/, ''),
    apiKey: String(process.env.DSH_IMAGE_STUDIO_AGENT_API_KEY ?? '').trim(),
  }
}

/**
 * Validate the single reference image a ComfyUI run may carry.
 *
 * ComfyUI workflows take one init image, not a batch, so only the first entry
 * is considered — matching what `comfyPayload` in the browser half sends.
 */
function readComfyReference(value) {
  if (value === undefined || value === null) return { image: null, name: '' }
  if (typeof value !== 'object' || Array.isArray(value)) return { error: '参考图格式无效' }
  const encoded = typeof value.data === 'string' ? value.data : ''
  if (encoded === '') return { image: null, name: '' }
  let bytes
  try {
    bytes = Buffer.from(encoded, 'base64')
  } catch {
    return { error: '参考图数据不是有效的 base64' }
  }
  if (bytes.length === 0) return { error: '参考图数据为空' }
  if (bytes.length > MAX_IMAGE_BYTES) {
    return { error: '单张参考图超过 ' + String(Math.round(MAX_IMAGE_BYTES / 1024 / 1024)) + ' MB 上限' }
  }
  const mediaType = imageMediaType(value.mediaType)
  if (!mediaType) return { error: '参考图必须是 PNG、JPEG、WebP 或 GIF' }
  return { image: { data: new Uint8Array(bytes), mediaType }, name: typeof value.name === 'string' ? value.name : '' }
}

/** An upload file name ComfyUI will accept, from the browser's file name. */
function uploadName(name, mediaType) {
  const base = String(name ?? '').replace(/[\\/]/g, '_').replace(/^\.+/, '').trim()
  const safe = base === '' ? 'reference' : base
  const extension = '.' + extensionFor(mediaType)
  return safe.toLowerCase().endsWith(extension) ? safe : safe.replace(/\.[A-Za-z0-9]{1,5}$/, '') + extension
}

/** Prefer a non-empty body value, then the stored configuration, then empty. */
function stringOr(value, fallback) {
  if (typeof value === 'string' && value.trim() !== '') return value.trim()
  return typeof fallback === 'string' ? fallback : ''
}

/** The configuration fields that are safe to hand to the browser. */
function publicConfig(config) {
  const copy = { ...config }
  delete copy.agentApiKey
  return copy
}

/**
 * Read a request body as text.
 *
 * @param req - the incoming HTTP request.
 * @returns the decoded body, or undefined when empty.
 */
async function readBody(req, limit) {
  if (Number(req.headers['content-length'] ?? 0) > limit) {
    req.resume()
    throw Object.assign(new Error('请求体超过大小限制'), { status: 413 })
  }
  const chunks = []
  let size = 0
  for await (const chunk of req) {
    size += chunk.length
    if (size <= limit) chunks.push(chunk)
  }
  if (size > limit) throw Object.assign(new Error('请求体超过大小限制'), { status: 413 })
  const body = Buffer.concat(chunks).toString('utf8')
  let parsed
  try { parsed = JSON.parse(body) } catch { throw new Error('请求体必须是有效JSON') }
  if (parsed === null || typeof parsed !== 'object' || Array.isArray(parsed)) throw new Error('请求体必须是JSON对象')
  return body
}

/**
 * Forward a request to the project Agent and relay its JSON answer.
 *
 * The embedded LLM config/assistant routes are plain relays and use this. The
 * ComfyUI mode does not: it talks to ComfyUI directly through comfy.js.
 *
 * @param res - the response to write.
 * @param agentPath - the agent-relative path to call.
 * @param body - an optional JSON request body.
 * @param timeoutMs - the upstream budget in milliseconds.
 */
async function proxyJson(res, agentPath, body, timeoutMs, options) {
  const config = await options.store.load()
  const { baseUrl, apiKey } = agentTarget(config)
  const controller = Number.isFinite(timeoutMs) && timeoutMs > 0 ? new AbortController() : null
  const timer = controller ? setTimeout(() => controller.abort(), timeoutMs) : null
  try {
    const upstream = await fetch(baseUrl + agentPath, {
      method: body === undefined ? 'GET' : 'POST',
      headers: requestHeaders(apiKey, body !== undefined),
      body,
      signal: controller?.signal,
    })
    const text = await upstream.text()
    let parsed
    try { parsed = JSON.parse(text) } catch { parsed = undefined }
    res.writeHead(upstream.status, {
      'Content-Type': 'application/json; charset=utf-8',
      'Cache-Control': 'no-store',
    })
    res.end(parsed === undefined ? JSON.stringify({ error: text.slice(0, 500) }) : text)
  } catch (error) {
    const aborted = error instanceof Error && error.name === 'AbortError'
    sendJson(res, aborted ? 504 : 502, {
      error: aborted
        ? '请求超时（' + String(Math.round(timeoutMs / 1000)) + ' 秒）'
        : '无法连接或读取 Agent：请检查 Agent 是否已启动。',
    })
  } finally {
    if (timer !== null) clearTimeout(timer)
  }
}

/** Build headers without exposing the Agent key to the browser. */
function requestHeaders(apiKey, hasJsonBody) {
  const headers = {}
  if (hasJsonBody) headers['Content-Type'] = 'application/json'
  if (apiKey) headers.Authorization = 'Bearer ' + apiKey
  return Object.keys(headers).length === 0 ? undefined : headers
}

/**
 * A tiny JSON-file configuration store.
 *
 * The panel owns its own settings because the host settings service has no
 * section-installation surface for a composed bundle to use; a cache-directory
 * file keeps the settings next to the images they produced.
 */
function createConfigStore(overrides) {
  const merged = { ...DEFAULT_CONFIG }
  for (const key of Object.keys(DEFAULT_CONFIG)) {
    const value = overrides?.[key]
    if (value === undefined || value === null || value === '') continue
    merged[key] = typeof DEFAULT_CONFIG[key] === 'number' ? Number(value) : String(value)
  }
  let cache = null
  async function load() {
    if (cache) return cache
    cache = { ...merged }
    try {
      const parsed = JSON.parse(await readFile(CONFIG_PATH, 'utf8'))
      if (parsed !== null && typeof parsed === 'object' && !Array.isArray(parsed)) {
        for (const key of Object.keys(DEFAULT_CONFIG)) {
          const value = parsed[key]
          if (typeof DEFAULT_CONFIG[key] === 'number' && typeof value === 'number') cache[key] = value
          else if (typeof value === 'string') cache[key] = value
        }
      }
    } catch {
      // No stored configuration yet, or it is unreadable: defaults stand.
    }
    return cache
  }
  return {
    load,
    async save(patch) {
      const current = await load()
      const next = { ...current }
      for (const [key, value] of Object.entries(patch)) {
        if (key in DEFAULT_CONFIG && value !== '') next[key] = value
      }
      await mkdir(DATA_DIR, { recursive: true })
      const temporary = CONFIG_PATH + '.' + randomBytes(4).toString('hex') + '.tmp'
      await writeFile(temporary, JSON.stringify(next, null, 2) + '\n')
      await renameInto(temporary, CONFIG_PATH)
      cache = next
      return next
    },
  }
}

/** Replace a file atomically, tolerating a concurrent reader. */
async function renameInto(source, target) {
  const { rename } = await import('node:fs/promises')
  await rename(source, target)
}

/**
 * Write one JSON response.
 *
 * @param res - the response to write.
 * @param status - the HTTP status code.
 * @param value - the JSON-serializable body.
 */
function sendJson(res, status, value) {
  if (res.headersSent || res.writableEnded) return
  const body = JSON.stringify(value)
  res.writeHead(status, {
    'Content-Type': 'application/json; charset=utf-8',
    'Content-Length': String(Buffer.byteLength(body)),
    'Cache-Control': 'no-store',
  })
  res.end(body)
}
